namespace LibraryManagementSystemAPI.Entities
{
	public class Member : BaseEntity
	{
		// Generated by a PostgreSQL sequence: 1, 2, 3, ...
		// Shown to people as "M-000001"
		public int MembershipNumber { get; set; }

		public required string FirstName { get; set; }
		public required string LastName { get; set; }

		// Stored trimmed and lowercase
		public required string Email { get; set; }
		public string? PhoneNumber { get; set; }

		public MemberStatus Status { get; set; } = MemberStatus.Active;
		public string? SuspensionReason { get; set; }

		public DateOnly MembershipExpiresOn { get; set; }

		// ---------- Questions about this member ----------
		// "today" is passed in, so these are easy to test

		public bool IsMembershipExpired(DateOnly today) =>
			MembershipExpiresOn < today;

		public bool CanBorrow(DateOnly today) =>
			Status == MemberStatus.Active && !IsMembershipExpired(today);
	}
}